for (const locale of ["de", "fr", "es", "it", "pl"] as const) {
  for (const slug of Object.keys(en)) {
    const base = en[slug];
    const translated = fallback[locale][slug];
    const closing = localizedClosingParagraphs[locale];
    localized[locale][slug] = {
      intro: translated.intro,
      sections: base.sections.map((_, index) => {
        const paragraphs = [localizedParagraphs[locale][index], ...(localizedExpansions[locale][slug]?.[index] ?? [])];
        if (slug === "usfans-spreadsheet-guide" && index === 8) paragraphs.push(closing.spreadsheet);
        if (slug === "usfans-qc-photos-guide" && index === 8) paragraphs.push(...closing.qc);
        if (slug === "usfans-shipping-cost-guide" && index === 8) paragraphs.push(closing.shippingEstimate);
        if (slug === "usfans-shipping-cost-guide" && index === 9) paragraphs.push(...closing.shippingSplit);
        return { h: translated.headings[index], paragraphs };
      })
    };
  }
}

export const articleContent: Record<ArticleLocale, Record<string, ArticleContent>> = { en, ...localized };
